mapper.select:
SELECT 
FROM water_intake_log
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND biz_date = #{bizDate}
  AND is_deleted = 0
ORDER BY COALESCE(recorded_at, gmt_created) ASC

SELECT COALESCE(SUM(amount_ml), 0)
FROM water_intake_log
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND biz_date = #{bizDate}
  AND is_deleted = 0

SELECT 
FROM water_intake_log
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND biz_date >= #{from}
  AND biz_date <= #{to}
  AND is_deleted = 0
ORDER BY biz_date ASC, COALESCE(recorded_at, gmt_created) ASC
